1	//! The look vocabulary (spec §11 GR-7, format 15):
2	//! [`Look`], the `video.look` a clip carries — one of the eight built-in
3	//! [`LookKind`]s or an imported `.cube` LUT (`lut`, GR-8, naming its media),
4	//! and how much of it — and each built-in kind's [`LookDefinition`], the
5	//! DATA the compositor bakes.
6	//!
7	//! **Rust decides, Metal does** (spec §7): a look is defined here, as Color's
8	//! four keys, Light's nine and a [`SplitTone`], and published in the recipe
9	//! as that definition; the app bakes it on the GPU into a 33³ lattice with
10	//! the layer stage's own functions and mixes it at step 4d. Nothing here is
11	//! a colour table: the eight are Frame Job's own first numbers (tuned by the
12	//! owner at GR7), built from the textbook operations tone already uses — the
13	//! Concat rule (`designs/adr/effects-survey.md`) stands.
14	//!
15	//! Re-exported whole by `model_props.rs`, which `model.rs` re-exports whole
16	//! in turn, so `crate::model::Look` resolves like every other property type.
17	//!
18	//! **The declaration ORDER of [`LookKind`] is the gallery's and the menu's**
19	//! (GR-7): append, never reorder; `Lut` comes last and is not one of
20	//! [`LookKind::BUILT_IN`]. The JSON spelling of each variant is persisted, so
21	//! a rename needs a migration step. Closed: a misspelt kind is refused at the
22	//! serde boundary naming the nine, because there is no neutral look to fall
23	//! back to — "no look" is `video.look` absent. What `media` must name, and
24	//! when, is `lut.rs`'s.
25	
26	use serde::{Deserialize, Serialize};
27	
28	use crate::model::ColorAdjust;
29	
30	/// The amount a look takes when a patch names only its kind: all of it
31	/// (GR-7 choice 2).
32	pub const LOOK_DEFAULT_AMOUNT: f64 = 1.0;
33	
34	fn default_look_amount() -> f64 {
35	    LOOK_DEFAULT_AMOUNT
36	}
37	
38	/// The eight built-in looks, in the gallery's order (GR-7 choice 1), and
39	/// `Lut`, an imported `.cube` file (GR-8), whose table is the media's.
40	#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
41	#[serde(rename_all = "snake_case")]
42	pub enum LookKind {
43	    Warm,
44	    Cool,
45	    TealOrange,
46	    Vivid,
47	    Faded,
48	    Vintage,
49	    Dramatic,
50	    BlackWhite,
51	    Lut,
52	}
53	
54	/// A clip's look: which, and how much (0…1, `props_check.rs` refuses
55	/// outside it). `kind` has NO default, so a `look` without one does not read
56	/// — a patch naming only an amount on a clip that has no look is refused,
57	/// and an action's end that does so evaluates as no look (`actions.rs`).
58	/// `media` is the LUT's media id, with `Lut` only (GR-8; `lut.rs` holds the
59	/// rule), written between `kind` and `amount` and only when set.
60	#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
61	pub struct Look {
62	    pub kind: LookKind,
63	    #[serde(default, skip_serializing_if = "Option::is_none")]
64	    pub media: Option<u32>,
65	    #[serde(default = "default_look_amount")]
66	    pub amount: f64,
67	}
68	
69	/// Two hues pushed into the shadows and the highlights, the one building
70	/// block a look has that Light does not (GR-7 choice 4). Hues in degrees,
71	/// amounts 0…1; the bake weights each by (1 − Y)² and Y², Y the luma.
72	#[derive(Debug, Clone, Copy, Default, PartialEq, Serialize)]
73	pub struct SplitTone {
74	    pub shadow_hue: f64,
75	    pub shadow_amount: f64,
76	    pub highlight_hue: f64,
77	    pub highlight_amount: f64,
78	}
79	
80	/// What a look IS: the colour, tone and split tone its lattice is baked
81	/// from. Published in the recipe under the layer's `look` key.
82	#[derive(Debug, Clone, Copy, Default, PartialEq, Serialize)]
83	pub struct LookDefinition {
84	    pub color: ColorAdjust,
85	    pub split: SplitTone,
86	}
87	
88	impl LookKind {
89	    /// The eight built-in kinds, in declaration order (`Lut` is not one).
90	    pub const BUILT_IN: [LookKind; 8] = [
91	        LookKind::Warm,
92	        LookKind::Cool,
93	        LookKind::TealOrange,
94	        LookKind::Vivid,
95	        LookKind::Faded,
96	        LookKind::Vintage,
97	        LookKind::Dramatic,
98	        LookKind::BlackWhite,
99	    ];
100	
101	    /// The kind's definition — GR-7's table, every unlisted value 0; `None`
102	    /// for `Lut`, whose table is a file's.
103	    pub fn definition(self) -> Option<LookDefinition> {
104	        let neutral = ColorAdjust::default();
105	        let none = SplitTone::default();
106	        let (color, split) = match self {
107	            LookKind::Lut => return None,
108	            LookKind::Warm => (
109	                ColorAdjust {
110	                    temperature: 0.35,
111	                    tint: 0.05,
112	                    vibrance: 0.10,
113	                    ..neutral
114	                },
115	                SplitTone {
116	                    highlight_hue: 40.0,
117	                    highlight_amount: 0.25,
118	                    ..none
119	                },
120	            ),
121	            LookKind::Cool => (
122	                ColorAdjust {
123	                    temperature: -0.35,
124	                    contrast: 0.05,
125	                    ..neutral
126	                },
127	                SplitTone {
128	                    shadow_hue: 215.0,
129	                    shadow_amount: 0.30,
130	                    ..none
131	                },
132	            ),
133	            LookKind::TealOrange => (
134	                ColorAdjust {
135	                    contrast: 0.15,
136	                    vibrance: 0.20,
137	                    ..neutral
138	                },
139	                SplitTone {
140	                    shadow_hue: 190.0,
141	                    shadow_amount: 0.60,
142	                    highlight_hue: 35.0,
143	                    highlight_amount: 0.45,
144	                },
145	            ),
146	            LookKind::Vivid => (
147	                ColorAdjust {
148	                    contrast: 0.15,
149	                    saturation: 0.10,
150	                    vibrance: 0.40,
151	                    whites: 0.20,
152	                    blacks: -0.20,
153	                    ..neutral
154	                },
155	                none,
156	            ),
157	            LookKind::Faded => (
158	                ColorAdjust {
159	                    contrast: -0.15,
160	                    saturation: -0.25,
161	                    highlights: -0.15,
162	                    fade: 0.60,
163	                    ..neutral
164	                },
165	                none,
166	            ),
167	            LookKind::Vintage => (
168	                ColorAdjust {
169	                    contrast: -0.05,
170	                    saturation: -0.30,
171	                    temperature: 0.25,
172	                    fade: 0.40,
173	                    ..neutral
174	                },
175	                SplitTone {
176	                    shadow_hue: 160.0,
177	                    shadow_amount: 0.30,
178	                    highlight_hue: 50.0,
179	                    highlight_amount: 0.35,
180	                },
181	            ),
182	            LookKind::Dramatic => (
183	                ColorAdjust {
184	                    exposure: -0.25,
185	                    contrast: 0.25,
186	                    saturation: -0.35,
187	                    highlights: -0.20,
188	                    shadows: -0.20,
189	                    ..neutral
190	                },
191	                SplitTone {
192	                    shadow_hue: 220.0,
193	                    shadow_amount: 0.20,
194	                    ..none
195	                },
196	            ),
197	            LookKind::BlackWhite => (
198	                ColorAdjust {
199	                    saturation: -1.0,
200	                    contrast: 0.20,
201	                    whites: 0.10,
202	                    blacks: -0.10,
203	                    ..neutral
204	                },
205	                none,
206	            ),
207	        };
208	        Some(LookDefinition { color, split })
209	    }
210	}
211	//! `.cube` LUTs as media and as looks (spec §11 GR-8): the rules a `lut`
212	//! media row and a `video.look {kind: "lut", media}` obey, written once for
213	//! every door that meets them.
214	//!
215	//! - **The row.** A LUT is media so it is referenced, relinked and
216	//!   consolidated like footage, but it has no picture of its own: its row
217	//!   carries no video, audio, alpha or duration ([`check_lut_fields`], which
218	//!   `edit_track.rs`'s `check_media_fields` calls for `add_media`, a
219	//!   relink's probe and a pasted media row), and it is never placed as a clip — `add_clip`,
220	//!   `insert_clip`, `overwrite_clip` and `add_background` answer
221	//!   [`lut_not_placeable`].
222	//! - **The look.** `media` is required with `lut` and goes with nothing
223	//!   else, and must name a `lut` media of the project
224	//!   ([`Project::check_look_media`], beside `check_adjustment_video` on the
225	//!   patch path and on every pasted group, and in `validate` for a file),
226	//!   through [`Project::check_lut_reference`], which `media_color.rs`'s
227	//!   `color.lut` shares. A
228	//!   patch naming a built-in kind and no `media` drops a stored one
229	//!   ([`normalise_look`]), so a built-in kind on a LUT clip replaces the LUT.
230	//! - **An action's end** is never checked against the media list
231	//!   (`set_action_end` checks shape only), so an end may name a LUT that is
232	//!   not there: the evaluator reads such a look as NO look
233	//!   ([`Project::evaluates_as_look`]), and `actions.rs` switches `media` at
234	//!   the end like a `kind`, so an id is never interpolated.
235	//! - **Removing a used LUT** ([`Project::remove_lut`]) refuses naming the
236	//!   clips whose base look it is and the media whose Camera Log it is (spec
237	//!   §11 GR-16, `media.color.lut`), or with `with_clips` clears those looks
238	//!   and conversions and keeps the clips and the media; ends are left alone
239	//!   (inert by the evaluator).
240	//! - **Paste** brings a LUT's row by path like any media; an id the payload
241	//!   does not carry becomes no look ([`remap_look_media`]) rather than
242	//!   another media's id.
243	
244	use std::collections::HashMap;
245	
246	use serde_json::Value;
247	
248	use crate::export_overrides::spelled;
249	use crate::model::{Clip, Look, LookKind, Media, MediaKind, Project, VideoProps};
250	use crate::outcome::Outcome;
251	
252	/// The refusal for `media` on a built-in kind.
253	fn media_goes_with_lut(kind: LookKind) -> String {
254	    format!("video.look.media goes with kind lut, not {}", spelled(kind))
255	}
256	
257	/// What `add_clip` and the other placing ops answer for a LUT: it is a look,
258	/// and the sentence says how to apply one.
259	pub(crate) fn lut_not_placeable(media: u32) -> String {
260	    format!(
261	        "media {media} is a LUT: apply it as a look (set_video {{look: {{kind: \"lut\", \
262	         media: {media}}}}}), it is not placed as a clip"
263	    )
264	}
265	
266	/// A `lut` row's own check: it has no picture or sound, so none of the
267	/// flags or a duration. Any other kind passes.
268	pub(crate) fn check_lut_fields(media: &Media) -> Result<(), String> {
269	    if media.kind == MediaKind::Lut
270	        && (media.has_video || media.has_audio || media.has_alpha || media.duration != 0)
271	    {
272	        return Err("a lut media has no video, audio, alpha or duration".to_string());
273	    }
274	    Ok(())
275	}
276	
277	/// After a video patch has merged: a patch that names a built-in `kind` and
278	/// no `media` drops a stored `media` (the built-in replaces the LUT), and a
279	/// patch that names `media` on a built-in kind is refused.
280	pub(crate) fn normalise_look(props: &mut VideoProps, patch: &Value) -> Result<(), String> {
281	    let Some(Value::Object(asked)) = patch.get("look") else {
282	        return Ok(());
283	    };
284	    let Some(look) = props.look.as_mut() else {
285	        return Ok(());
286	    };
287	    if look.kind == LookKind::Lut {
288	        return Ok(());
289	    }
290	    let names_media = asked.get("media").is_some_and(|media| !media.is_null());
291	    if names_media {
292	        return Err(media_goes_with_lut(look.kind));
293	    }
294	    if asked.get("kind").is_some_and(|kind| !kind.is_null()) {
295	        look.media = None;
296	    }
297	    Ok(())
298	}
299	
300	/// The LUT a clip's base look names, if it is a LUT look.
301	fn base_lut(clip: &Clip) -> Option<u32> {
302	    let look = clip.video.as_ref()?.look?;
303	    (look.kind == LookKind::Lut).then_some(look.media).flatten()
304	}
305	
306	/// Every media id a clip's looks name: the base look's, then each action
307	/// end's `video.look.media`, in action order, without repeats. Paste's
308	/// absorb list, after the source's media.
309	pub(crate) fn look_media_ids(clip: &Clip) -> Vec<u32> {
310	    let mut ids: Vec<u32> = Vec::new();
311	    let base = clip.video.as_ref().and_then(|video| video.look?.media);
312	    let ends = clip.actions.iter().filter_map(|action| {
313	        let media = action.end.get("video")?.get("look")?.get("media")?;
314	        u32::try_from(media.as_u64()?).ok()
315	    });
316	    for id in base.into_iter().chain(ends) {
317	        if !ids.contains(&id) {
318	            ids.push(id);
319	        }
320	    }
321	    ids
322	}
323	
324	/// Points a pasted clip's looks at this project's media ids. An id `map`
325	/// does not carry never stays (it could name another media here): the base
326	/// look becomes no look, and an end's look becomes `null`.
327	pub(crate) fn remap_look_media(clip: &mut Clip, map: &HashMap<u32, u32>) {
328	    if let Some(video) = clip.video.as_mut() {
329	        if let Some(id) = video.look.and_then(|look| look.media) {
330	            match map.get(&id) {
331	                Some(local) => {
332	                    if let Some(look) = video.look.as_mut() {
333	                        look.media = Some(*local);
334	                    }
335	                }
336	                None => video.look = None,
337	            }
338	        }
339	    }
340	    for action in clip.actions.iter_mut() {
341	        let Some(Value::Object(video)) = action.end.get_mut("video") else {
342	            continue;
343	        };
344	        let Some(Value::Object(look)) = video.get_mut("look") else {
345	            continue;
346	        };
347	        let Some(id) = look
348	            .get("media")
349	            .and_then(Value::as_u64)
350	            .and_then(|id| u32::try_from(id).ok())
351	        else {
352	            continue;
353	        };
354	        match map.get(&id) {
355	            Some(local) => {
356	                look.insert("media".to_string(), Value::from(*local));
357	            }
358	            None => {
359	                video.insert("look".to_string(), Value::Null);
360	            }
361	        }
362	    }
363	}
364	
365	impl Project {
366	    /// A reference to a LUT by media id, named by its `key`
367	    /// (`video.look.media`, `color.lut`): the id names a media of this
368	    /// project, and that media is a `lut`.
369	    pub(crate) fn check_lut_reference(&self, key: &str, id: u32) -> Result<(), String> {
370	        match self.media(id) {
371	            None => Err(format!("{key} {id} is not a media of this project")),
372	            Some(found) if found.kind != MediaKind::Lut => {
373	                let kind = spelled(found.kind);
374	                let article = if kind.starts_with(['a', 'e', 'i', 'o', 'u']) {
375	                    "an"
376	                } else {
377	                    "a"
378	                };
379	                Err(format!("{key} {id} is {article} {kind} media, not a lut"))
380	            }
381	            Some(_) => Ok(()),
382	        }
383	    }
384	
385	    /// A look's `media` against this project: required with `lut` and naming
386	    /// a `lut` media of it, and absent with a built-in kind.
387	    pub(crate) fn check_look_media(&self, props: &VideoProps) -> Result<(), String> {
388	        let Some(look) = props.look else {
389	            return Ok(());
390	        };
391	        match (look.kind, look.media) {
392	            (LookKind::Lut, None) => Err("video.look.media is required with kind lut".to_string()),
393	            (LookKind::Lut, Some(id)) => self.check_lut_reference("video.look.media", id),
394	            (kind, Some(_)) => Err(media_goes_with_lut(kind)),
395	            (_, None) => Ok(()),
396	        }
397	    }
398	
399	    /// Whether a merged look (an action's end laid over the base) draws: it
400	    /// decodes, and a LUT look names a `lut` media of this project. The
401	    /// evaluator writes `null` for one that does not.
402	    pub(crate) fn evaluates_as_look(&self, look: &Value) -> bool {
403	        let Ok(look) = serde_json::from_value::<Look>(look.clone()) else {
404	            return false;
405	        };
406	        look.kind != LookKind::Lut
407	            || look
408	                .media
409	                .and_then(|id| self.media(id))
410	                .is_some_and(|media| media.kind == MediaKind::Lut)
411	    }
412	
413	    /// `remove_media` for a LUT: refused naming the clips whose base look it
414	    /// is and the media whose Camera Log it is (spec §11 GR-16) unless
415	    /// `with_clips`, which clears those looks — on the timeline and in every
416	    /// nest — and those conversions, and keeps the clips and the media. Ends
417	    /// naming it are left: the evaluator reads them as no look.
418	    pub(crate) fn remove_lut(&self, media: u32, with_clips: bool) -> Result<Outcome, String> {
419	        let used: Vec<u32> = self
420	            .every_clip()
421	            .filter(|clip| base_lut(clip) == Some(media))
422	            .map(|clip| clip.id)
423	            .collect();
424	        let converted = self.media_converted_by(media);
425	        if !with_clips {
426	            let looks = crate::edit_track::clip_list(&used);
427	            let refusal = match (used.is_empty(), converted.is_empty()) {
428	                (true, true) => None,
429	                (false, true) => Some(format!(
430	                    "media {media} is the look of {looks}; pass with_clips: true to remove it \
431	                     and clear their looks"
432	                )),
433	                (true, false) => Some(format!(
434	                    "media {media} is the Camera Log of {}; pass with_clips: true to remove it \
435	                     and clear it",
436	                    media_list(&converted)
437	                )),
438	                (false, false) => Some(format!(
439	                    "media {media} is the look of {looks} and the Camera Log of {}; pass \
440	                     with_clips: true to remove it and clear both",
441	                    media_list(&converted)
442	                )),
443	            };
444	            if let Some(refusal) = refusal {
445	                return Ok(Outcome::Refused(refusal));
446	            }
447	        }
448	        let mut next = self.clone();
449	        let clips = next
450	            .clips
451	            .iter_mut()
452	            .chain(next.nests.iter_mut().flat_map(|nest| nest.clips.iter_mut()));
453	        for clip in clips {
454	            if base_lut(clip) == Some(media) {
455	                if let Some(video) = clip.video.as_mut() {
456	                    video.look = None;
457	                }
458	            }
459	        }
460	        for row in next.media.iter_mut() {
461	            if converted.contains(&row.id) {
462	                row.color = row.color.and_then(|color| color.without_camera_log());
463	            }
464	        }
465	        next.media.retain(|m| m.id != media);
466	        self.finish(next)
467	    }
468	}
469	
470	/// Media ids as a sentence names them, `clip_list`'s way: "media 3",
471	/// "media 3 and 5", "media 3, 4, 5 and 2 more".
472	fn media_list(ids: &[u32]) -> String {
473	    let listed = crate::edit_track::clip_list(ids);
474	    let rest = listed
475	        .strip_prefix("clips ")
476	        .or_else(|| listed.strip_prefix("clip "))
477	        .unwrap_or(&listed);
478	    format!("media {rest}")
479	}
480	//! A `.cube` 3D LUT file read into its lattice (spec §11 GR-8): the one
481	//! parser, which `ffi_cube.rs` exports for the app's import probe and its
482	//! texture upload, so a file the import accepted is the file the compositor
483	//! draws.
484	//!
485	//! **What is read** (GR-8 choice 7): 3D only; `LUT_3D_SIZE` 2–65; `TITLE`;
486	//! `#` comment lines; blank lines; CRLF; a UTF-8 BOM; `DOMAIN_MIN 0 0 0`,
487	//! `DOMAIN_MAX 1 1 1` and `LUT_3D_INPUT_RANGE 0 1`, which are the defaults
488	//! and so change nothing; table rows of three finite numbers, any value
489	//! (the compositor clamps to 0–1 when it draws). Everything else is
490	//! REFUSED by name rather than guessed at — a 1D LUT, another size, a
491	//! domain that is not the default, an unknown keyword, a keyword after the
492	//! table, a short or long table, a token that is not a number — in a
493	//! lowercase sentence naming the 1-based line and what was on it, which the
494	//! app prefixes with the file's name.
495	//!
496	//! The table's order is the format's: **red changes fastest**, then green,
497	//! then blue, and [`Cube::rgb`] keeps it, so row `r + g·n + b·n²` is the
498	//! output for input `(r, g, b) / (n − 1)` — exactly a 3D texture's texel
499	//! order, which is why the app uploads it unchanged.
500	//!
501	//! Written from the format's own description; nothing of Concat (the
502	//! effects survey's licensing rule) is read or carried.
503	
504	use crate::format::RC_CUBE_MAX_BYTES;
505	
506	/// The smallest lattice read: two points an axis, the corners.
507	pub const CUBE_SIZE_MIN: u32 = 2;
508	/// The largest: 65 points an axis (274,625 rows), the size the common
509	/// grading tools write at most.
510	pub const CUBE_SIZE_MAX: u32 = 65;
511	
512	/// A parsed 3D LUT: `size` points an axis, and `size³` rows of red, green
513	/// and blue, red fastest, as the file listed them.
514	#[derive(Debug, Clone, PartialEq)]
515	pub struct Cube {
516	    pub size: u32,
517	    pub rgb: Vec<f32>,
518	}
519	
520	/// One keyword the parser has a rule for.
521	enum Keyword {
522	    Title,
523	    Size,
524	    DomainMin,
525	    DomainMax,
526	    InputRange,
527	    OneD,
528	    Unknown,
529	}
530	
531	impl Keyword {
532	    fn of(word: &str) -> Keyword {
533	        match word {
534	            "TITLE" => Keyword::Title,
535	            "LUT_3D_SIZE" => Keyword::Size,
536	            "DOMAIN_MIN" => Keyword::DomainMin,
537	            "DOMAIN_MAX" => Keyword::DomainMax,
538	            "LUT_3D_INPUT_RANGE" => Keyword::InputRange,
539	            "LUT_1D_SIZE" | "LUT_1D_INPUT_RANGE" => Keyword::OneD,
540	            _ => Keyword::Unknown,
541	        }
542	    }
543	}
544	
545	/// A token as a number: `Ok` only for a finite one, else the sentence that
546	/// names the token (`"0.5x" is not a number`, `nan is not a finite number`).
547	fn number(token: &str, line: usize) -> Result<f64, String> {
548	    match token.parse::<f64>() {
549	        Ok(value) if value.is_finite() => Ok(value),
550	        Ok(_) => Err(format!("line {line}: {token} is not a finite number")),
551	        Err(_) => Err(format!("line {line}: \"{token}\" is not a number")),
552	    }
553	}
554	
555	/// A keyword's numbers, exactly `count` of them, each finite.
556	fn numbers(word: &str, rest: &[&str], count: usize, line: usize) -> Result<Vec<f64>, String> {
557	    if rest.len() != count {
558	        let noun = if count == 1 { "number" } else { "numbers" };
