590	impl Cube {
591	    /// Reads a `.cube` file's bytes; `Err` is the rule's own sentence.
592	    pub fn parse(bytes: &[u8]) -> Result<Cube, String> {
593	        if bytes.len() > RC_CUBE_MAX_BYTES {
594	            return Err("the file is larger than 32 MB".to_string());
595	        }
596	        let text = match std::str::from_utf8(bytes) {
597	            Ok(text) if !text.contains('\0') => text,
598	            _ => return Err("the file is not text".to_string()),
599	        };
600	        let text = text.strip_prefix('\u{feff}').unwrap_or(text);
601	        let mut size: Option<u32> = None;
602	        let mut rgb: Vec<f32> = Vec::new();
603	        let mut rows: usize = 0;
604	        let mut wanted: usize = 0;
605	        for (index, raw) in text.lines().enumerate() {
606	            let line = index + 1;
607	            let trimmed = raw.trim();
608	            if trimmed.is_empty() || trimmed.starts_with('#') {
609	                continue;
610	            }
611	            let tokens: Vec<&str> = trimmed.split_whitespace().collect();
612	            let first = tokens[0];
613	            // A table row begins with something `f64` reads (`nan` and
614	            // `inf` included, refused below as not finite); a keyword with
615	            // a letter or an underscore. Anything else is a row whose first
616	            // token is not a number.
617	            let is_keyword = first.parse::<f64>().is_err()
618	                && first.starts_with(|c: char| c.is_ascii_alphabetic() || c == '_');
619	            if is_keyword {
620	                let keyword = Keyword::of(first);
621	                match keyword {
622	                    Keyword::OneD => {
623	                        return Err(format!(
624	                            "line {line}: {first} is a 1D LUT; only 3D LUTs are read"
625	                        ))
626	                    }
627	                    Keyword::Unknown => {
628	                        return Err(format!("line {line}: unknown keyword {first}"))
629	                    }
630	                    _ => {}
631	                }
632	                if rows > 0 {
633	                    return Err(format!("line {line}: {first} comes after the table"));
634	                }
635	                let rest = &tokens[1..];
636	                match keyword {
637	                    Keyword::Title => {}
638	                    Keyword::Size => {
639	                        if size.is_some() {
640	                            return Err(format!("line {line}: a second LUT_3D_SIZE"));
641	                        }
642	                        let value = numbers(first, rest, 1, line)?[0];
643	                        if value.fract() != 0.0 {
644	                            return Err(format!(
645	                                "line {line}: LUT_3D_SIZE {} is not a whole number",
646	                                rest[0]
647	                            ));
648	                        }
649	                        if value < f64::from(CUBE_SIZE_MIN) || value > f64::from(CUBE_SIZE_MAX) {
650	                            return Err(format!(
651	                                "line {line}: LUT_3D_SIZE {} is outside {CUBE_SIZE_MIN}–{CUBE_SIZE_MAX}",
652	                                rest[0]
653	                            ));
654	                        }
655	                        let n = value as u32;
656	                        size = Some(n);
657	                        wanted = (n as usize).pow(3);
658	                        rgb.reserve_exact(wanted * 3);
659	                    }
660	                    Keyword::DomainMin => {
661	                        default_domain(first, rest, &[0.0, 0.0, 0.0], "0 0 0", line)?
662	                    }
663	                    Keyword::DomainMax => {
664	                        default_domain(first, rest, &[1.0, 1.0, 1.0], "1 1 1", line)?
665	                    }
666	                    Keyword::InputRange => default_domain(first, rest, &[0.0, 1.0], "0 1", line)?,
667	                    Keyword::OneD | Keyword::Unknown => {}
668	                }
669	                continue;
670	            }
671	            let values = tokens
672	                .iter()
673	                .map(|token| number(token, line))
674	                .collect::<Result<Vec<f64>, String>>()?;
675	            if values.len() != 3 {
676	                return Err(format!(
677	                    "line {line}: a table row has 3 numbers, not {}",
678	                    values.len()
679	                ));
680	            }
681	            rows += 1;
682	            // Only the rows the size asks for are kept; the rest are
683	            // counted, so a long table is named by its count.
684	            if size.is_some() && rows <= wanted {
685	                rgb.extend(values.into_iter().map(stored));
686	            }
687	        }
688	        let Some(size) = size else {
689	            return Err("no LUT_3D_SIZE line".to_string());
690	        };
691	        if rows != wanted {
692	            return Err(format!(
693	                "LUT_3D_SIZE {size} needs {wanted} table rows, not {rows}"
694	            ));
695	        }
696	        Ok(Cube { size, rgb })
697	    }
