257	/// What `add_clip` and the other placing ops answer for a LUT: it is a look,
258	/// and the sentence says how to apply one.
259	pub(crate) fn lut_not_placeable(media: u32) -> String {
260	    format!(
261	        "media {media} is a LUT: apply it as a look (set_video {{look: {{kind: \"lut\", \
262	         media: {media}}}}}), it is not placed as a clip"
263	    )
264	}
