266	/// A `lut` row's own check: it has no picture or sound, so none of the
267	/// flags or a duration. Any other kind passes.
268	pub(crate) fn check_lut_fields(media: &Media) -> Result<(), String> {
269	    if media.kind == MediaKind::Lut
270	        && (media.has_video || media.has_audio || media.has_alpha || media.duration != 0)
271	    {
272	        return Err("a lut media has no video, audio, alpha or duration".to_string());
273	    }
274	    Ok(())
275	}
