277	/// After a video patch has merged: a patch that names a built-in `kind` and
278	/// no `media` drops a stored `media` (the built-in replaces the LUT), and a
279	/// patch that names `media` on a built-in kind is refused.
280	pub(crate) fn normalise_look(props: &mut VideoProps, patch: &Value) -> Result<(), String> {
281	    let Some(Value::Object(asked)) = patch.get("look") else {
282	        return Ok(());
283	    };
284	    let Some(look) = props.look.as_mut() else {
285	        return Ok(());
286	    };
287	    if look.kind == LookKind::Lut {
288	        return Ok(());
289	    }
290	    let names_media = asked.get("media").is_some_and(|media| !media.is_null());
291	    if names_media {
292	        return Err(media_goes_with_lut(look.kind));
293	    }
294	    if asked.get("kind").is_some_and(|kind| !kind.is_null()) {
295	        look.media = None;
296	    }
297	    Ok(())
298	}
