306	/// Every media id a clip's looks name: the base look's, then each action
307	/// end's `video.look.media`, in action order, without repeats. Paste's
308	/// absorb list, after the source's media.
309	pub(crate) fn look_media_ids(clip: &Clip) -> Vec<u32> {
310	    let mut ids: Vec<u32> = Vec::new();
311	    let base = clip.video.as_ref().and_then(|video| video.look?.media);
312	    let ends = clip.actions.iter().filter_map(|action| {
313	        let media = action.end.get("video")?.get("look")?.get("media")?;
314	        u32::try_from(media.as_u64()?).ok()
315	    });
316	    for id in base.into_iter().chain(ends) {
317	        if !ids.contains(&id) {
318	            ids.push(id);
319	        }
320	    }
321	    ids
322	}
