365	impl Project {
366	    /// A reference to a LUT by media id, named by its `key`
367	    /// (`video.look.media`, `color.lut`): the id names a media of this
368	    /// project, and that media is a `lut`.
369	    pub(crate) fn check_lut_reference(&self, key: &str, id: u32) -> Result<(), String> {
370	        match self.media(id) {
371	            None => Err(format!("{key} {id} is not a media of this project")),
372	            Some(found) if found.kind != MediaKind::Lut => {
373	                let kind = spelled(found.kind);
374	                let article = if kind.starts_with(['a', 'e', 'i', 'o', 'u']) {
375	                    "an"
376	                } else {
377	                    "a"
378	                };
379	                Err(format!("{key} {id} is {article} {kind} media, not a lut"))
380	            }
381	            Some(_) => Ok(()),
382	        }
383	    }
