385	    /// A look's `media` against this project: required with `lut` and naming
386	    /// a `lut` media of it, and absent with a built-in kind.
387	    pub(crate) fn check_look_media(&self, props: &VideoProps) -> Result<(), String> {
388	        let Some(look) = props.look else {
389	            return Ok(());
390	        };
391	        match (look.kind, look.media) {
392	            (LookKind::Lut, None) => Err("video.look.media is required with kind lut".to_string()),
393	            (LookKind::Lut, Some(id)) => self.check_lut_reference("video.look.media", id),
394	            (kind, Some(_)) => Err(media_goes_with_lut(kind)),
395	            (_, None) => Ok(()),
396	        }
397	    }
