480	//! A `.cube` 3D LUT file read into its lattice (spec §11 GR-8): the one
481	//! parser, which `ffi_cube.rs` exports for the app's import probe and its
482	//! texture upload, so a file the import accepted is the file the compositor
483	//! draws.
484	//!
485	//! **What is read** (GR-8 choice 7): 3D only; `LUT_3D_SIZE` 2–65; `TITLE`;
486	//! `#` comment lines; blank lines; CRLF; a UTF-8 BOM; `DOMAIN_MIN 0 0 0`,
487	//! `DOMAIN_MAX 1 1 1` and `LUT_3D_INPUT_RANGE 0 1`, which are the defaults
488	//! and so change nothing; table rows of three finite numbers, any value
489	//! (the compositor clamps to 0–1 when it draws). Everything else is
490	//! REFUSED by name rather than guessed at — a 1D LUT, another size, a
491	//! domain that is not the default, an unknown keyword, a keyword after the
492	//! table, a short or long table, a token that is not a number — in a
493	//! lowercase sentence naming the 1-based line and what was on it, which the
494	//! app prefixes with the file's name.
495	//!
496	//! The table's order is the format's: **red changes fastest**, then green,
497	//! then blue, and [`Cube::rgb`] keeps it, so row `r + g·n + b·n²` is the
498	//! output for input `(r, g, b) / (n − 1)` — exactly a 3D texture's texel
499	//! order, which is why the app uploads it unchanged.
500	//!
501	//! Written from the format's own description; nothing of Concat (the
502	//! effects survey's licensing rule) is read or carried.
503	
504	use crate::format::RC_CUBE_MAX_BYTES;
505	
506	/// The smallest lattice read: two points an axis, the corners.
507	pub const CUBE_SIZE_MIN: u32 = 2;
508	/// The largest: 65 points an axis (274,625 rows), the size the common
509	/// grading tools write at most.
510	pub const CUBE_SIZE_MAX: u32 = 65;
511	
512	/// A parsed 3D LUT: `size` points an axis, and `size³` rows of red, green
513	/// and blue, red fastest, as the file listed them.
514	#[derive(Debug, Clone, PartialEq)]
515	pub struct Cube {
516	    pub size: u32,
517	    pub rgb: Vec<f32>,
518	}
519	
520	/// One keyword the parser has a rule for.
521	enum Keyword {
522	    Title,
523	    Size,
524	    DomainMin,
525	    DomainMax,
526	    InputRange,
527	    OneD,
528	    Unknown,
529	}
530	
531	impl Keyword {
532	    fn of(word: &str) -> Keyword {
533	        match word {
534	            "TITLE" => Keyword::Title,
535	            "LUT_3D_SIZE" => Keyword::Size,
536	            "DOMAIN_MIN" => Keyword::DomainMin,
537	            "DOMAIN_MAX" => Keyword::DomainMax,
538	            "LUT_3D_INPUT_RANGE" => Keyword::InputRange,
539	            "LUT_1D_SIZE" | "LUT_1D_INPUT_RANGE" => Keyword::OneD,
540	            _ => Keyword::Unknown,
541	        }
542	    }
543	}
544	
545	/// A token as a number: `Ok` only for a finite one, else the sentence that
546	/// names the token (`"0.5x" is not a number`, `nan is not a finite number`).
547	fn number(token: &str, line: usize) -> Result<f64, String> {
548	    match token.parse::<f64>() {
549	        Ok(value) if value.is_finite() => Ok(value),
550	        Ok(_) => Err(format!("line {line}: {token} is not a finite number")),
551	        Err(_) => Err(format!("line {line}: \"{token}\" is not a number")),
552	    }
553	}
554	
555	/// A keyword's numbers, exactly `count` of them, each finite.
556	fn numbers(word: &str, rest: &[&str], count: usize, line: usize) -> Result<Vec<f64>, String> {
557	    if rest.len() != count {
558	        let noun = if count == 1 { "number" } else { "numbers" };
559	        return Err(format!("line {line}: {word} needs {count} {noun}"));
560	    }
561	    rest.iter().map(|token| number(token, line)).collect()
562	}
563	
564	/// A domain line holding its default, or the sentence that names what it
565	/// holds instead.
566	fn default_domain(
567	    word: &str,
568	    rest: &[&str],
569	    want: &[f64],
570	    shown: &str,
571	    line: usize,
572	) -> Result<(), String> {
573	    let found = numbers(word, rest, want.len(), line)?;
574	    if found.iter().zip(want).all(|(a, b)| a == b) {
575	        Ok(())
576	    } else {
577	        Err(format!(
578	            "line {line}: {word} must be {shown}, not {}",
579	            rest.join(" ")
580	        ))
581	    }
582	}
583	
584	/// A table value as stored: an `f64` past `f32`'s range is held at its
585	/// largest finite value, which draws the same once clamped to 0–1.
586	fn stored(value: f64) -> f32 {
587	    (value as f32).clamp(-f32::MAX, f32::MAX)
588	}
589	
590	impl Cube {
591	    /// Reads a `.cube` file's bytes; `Err` is the rule's own sentence.
592	    pub fn parse(bytes: &[u8]) -> Result<Cube, String> {
593	        if bytes.len() > RC_CUBE_MAX_BYTES {
594	            return Err("the file is larger than 32 MB".to_string());
595	        }
596	        let text = match std::str::from_utf8(bytes) {
597	            Ok(text) if !text.contains('\0') => text,
598	            _ => return Err("the file is not text".to_string()),
599	        };
600	        let text = text.strip_prefix('\u{feff}').unwrap_or(text);
601	        let mut size: Option<u32> = None;
602	        let mut rgb: Vec<f32> = Vec::new();
603	        let mut rows: usize = 0;
604	        let mut wanted: usize = 0;
